local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_GREET, 'HIHOOOO |PLAYERNAME|! <waves his hands>')
npcHandler:setMessage(MESSAGE_FAREWELL, 'YEAH, GO AWAY!')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'YEAH, GO AWAY!')
keywordHandler:addKeyword({'humans'}, StdModule.say, {npcHandler = npcHandler, text = 'A PROMISING RACE, SOME OF THEM ACTUALLY ADMIRE MECHANICS.'})
keywordHandler:addKeyword({'equipment'}, StdModule.say, {npcHandler = npcHandler, text = 'YOU ARE TOO STUPID FOR MOST OF OUR STUFF, BUT I COULD SELL YOU SOME CROSSBOWS.'})
