keywordHandler:addKeyword({'maryza'}, StdModule.say, {npcHandler = npcHandler, text = 'LOVELY, BUT PREDJUDICED AS MOST DWARFS ARE.'})
keywordHandler:addKeyword({'help'}, StdModule.say, {npcHandler = npcHandler, text = 'WHOM YOU ARE CALLING A WHELP, YOU &$(&*#!'})
keywordHandler:addKeyword({'army'}, StdModule.say, {npcHandler = npcHandler, text = 'ONE DAY OUR MACHINES WILL CHANGE THE ARMY STRUCTURES DRASTICALLY, JAWOLL!'})
keywordHandler:addKeyword({'time'}, StdModule.say, {npcHandler = npcHandler, text = 'ONE DAY I WILL CREATE A CLOCK FOR THE COLOSSUS'})
keywordHandler:addKeyword({'life'}, StdModule.say, {npcHandler = npcHandler, text = 'WHAT HIVE?'})
keywordHandler:addKeyword({'emperor'}, StdModule.say, {npcHandler = npcHandler, text = 'AT LEAST HES SMART ENOUGH TO LEAVE US ALONE, SO THERES HOPE FOR HIM.'})
keywordHandler:addKeyword({'offering'}, StdModule.say, {npcHandler = npcHandler, text = 'YES, THE MOST SOPHISTICATED ITEMS THEY BUY ARE CROSSBOWS.'})
keywordHandler:addKeyword({'citizen'}, StdModule.say, {npcHandler = npcHandler, text = 'YOU CAN BECOME CITIZEN IN THE HALL OF ANCIENTS.'})
keywordHandler:addKeyword({'colossus'}, StdModule.say, {npcHandler = npcHandler, text = 'NICE PIECE OF WORK. WOULD BE MORE FUN IF IT COULD MOVE AROUND... WE HAVE PLANS...'})
keywordHandler:addKeyword({'quest'}, StdModule.say, {npcHandler = npcHandler, text = 'BRING ME THE SCREWDRIVER OF KURIK AND I WILL REWARD YOU WITH A STEAMPOWERED SPIKESWORD!'})
keywordHandler:addKeyword({'plant'}, StdModule.say, {npcHandler = npcHandler, text = 'HEY! HOW DID YOU LEARN ABOUT OUR SECRET PLANT?'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'WHERE SHOULD I HOP?'})
keywordHandler:addKeyword({'uniform'}, StdModule.say, {npcHandler = npcHandler, text = 'NO, HERE IS NO UNICORN!'})
keywordHandler:addKeyword({'duria'}, StdModule.say, {npcHandler = npcHandler, text = 'KNIGHTS DO NOT HAVE THE BRAIN TO EVEN UNDERSTAND WHAT WE ARE OFFERING THEM.'})
keywordHandler:addKeyword({'name'}, StdModule.say, {npcHandler = npcHandler, text = 'I HAVE NO TIME FOR A GAME!'})
keywordHandler:addKeyword({'orcs'}, StdModule.say, {npcHandler = npcHandler, text = 'LET THEM COME, I AM WORKING ON A LITTLE SURPRISE FOR THEM! <chukles madly>'})
keywordHandler:addKeyword({'gold'}, StdModule.say, {npcHandler = npcHandler, text = 'DONATIONS ARE ALWAYS WELCOME!'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)
shopModule:addBuyableItem({'crossbow'}, 3349, 1150, 'crossbow')
shopModule:addBuyableItem({'bolt'}, 3446, 5, 'bolt')

npcHandler:addModule(FocusModule:new())

